package com.lucid.os.updater;
import android.app.Activity;import android.app.AlertDialog;import android.os.Bundle;import android.view.View;import android.widget.Button;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import org.json.JSONObject;import java.io.*;import java.net.HttpURLConnection;import java.net.URL;import java.security.MessageDigest;import java.util.Locale;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public final class MainActivity extends Activity {
 private static final String MANIFEST_URL="https://raw.githubusercontent.com/NAANG360/Lucid-OS/main/ota/stable.json", RECOVERY_ZIP="/sdcard/Download/LucidOS-update.zip";
 private static final int BG=0xfff2f0f8,INK=0xff222237,MUTED=0xff666580,BLUE=0xff0866ff;private final ExecutorService io=Executors.newSingleThreadExecutor();private TextView status;private Button check,download,install;private JSONObject release;private File verifiedZip;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(BG);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(28),dp(24),dp(24));sc.addView(root);add(root,text("L U C I D",12,BLUE,true),0);add(root,text("System Updater",32,INK,true),dp(8));add(root,text("Download, verify, and install updates using root and recovery.",15,MUTED,false),dp(4));LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(18),dp(18),dp(18),dp(18));android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(-1);shape.setCornerRadius(dp(22));card.setBackground(shape);add(root,card,dp(24));add(card,text("Device: "+android.os.Build.DEVICE+"\nAndroid: "+android.os.Build.VERSION.RELEASE+"\nBuild: "+android.os.Build.DISPLAY,14,INK,true),0);status=text("Updates have not been checked.");add(card,status,dp(16));check=new Button(this);check.setText("Check for updates");check.setOnClickListener(v->check());add(card,check,dp(12));download=new Button(this);download.setText("Download and verify");download.setEnabled(false);download.setOnClickListener(v->download());add(card,download,dp(8));install=new Button(this);install.setText("Install update (root + recovery)");install.setEnabled(false);install.setOnClickListener(v->confirmInstall());add(card,install,dp(8));add(root,text("Requires working root access and compatible TWRP/OrangeFox recovery supporting openrecoveryscript. Keep the phone charged and back up important data first. If recovery does not support the script, it will not install automatically.",12,MUTED,false),dp(20));setContentView(sc);}
 private void check(){check.setEnabled(false);status.setText("Checking update manifest…");io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(MANIFEST_URL).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");if(c.getResponseCode()!=200)throw new Exception("Manifest HTTP "+c.getResponseCode());ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] x=new byte[8192];int n;while((n=in.read(x))!=-1)b.write(x,0,n);}c.disconnect();JSONObject m=new JSONObject(new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));if(!"lavender".equals(m.optString("device")))throw new Exception("Manifest device mismatch");String url=m.getString("url"),sha=m.getString("sha256");if(!url.startsWith("https://"))throw new Exception("Refusing non-HTTPS URL");if(!sha.matches("(?i)[0-9a-f]{64}")||sha.matches("0{64}"))throw new Exception("Invalid or placeholder checksum");release=m;runOnUiThread(()->{status.setText("Update "+m.optString("version","unknown")+" available.\n"+m.optString("changelog",""));check.setEnabled(true);download.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("Update check failed: "+e.getMessage());check.setEnabled(true);download.setEnabled(false);});}});}
 private void download(){if(release==null)return;download.setEnabled(false);install.setEnabled(false);status.setText("Downloading update…");io.execute(()->{File out=new File(getFilesDir(),"lucidos-update.zip");try{HttpURLConnection c=(HttpURLConnection)new URL(release.getString("url")).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(60000);if(c.getResponseCode()!=200)throw new Exception("Download HTTP "+c.getResponseCode());try(BufferedInputStream in=new BufferedInputStream(c.getInputStream());FileOutputStream os=new FileOutputStream(out)){byte[] buf=new byte[131072];int n;while((n=in.read(buf))!=-1)os.write(buf,0,n);}c.disconnect();String actual=sha256(out);if(!actual.equalsIgnoreCase(release.getString("sha256")))throw new Exception("SHA-256 mismatch; package deleted");verifiedZip=out;runOnUiThread(()->{status.setText("Download complete; SHA-256 verified. Ready for recovery installation.");download.setEnabled(true);install.setEnabled(true);Toast.makeText(this,"Update verified",Toast.LENGTH_LONG).show();});}catch(Exception e){out.delete();runOnUiThread(()->{status.setText("Download/verification failed: "+e.getMessage());download.setEnabled(true);install.setEnabled(false);});}});}
 private void confirmInstall(){new AlertDialog.Builder(this).setTitle("Install LucidOS update?").setMessage("The verified ZIP will be copied to Download, a recovery install script will be staged using root, and the phone will reboot into recovery. This overwrites system partitions and can leave the phone unbootable if the package/recovery is incompatible. Back up important data first. Continue?").setNegativeButton("Cancel",null).setPositiveButton("Reboot & install",(d,w)->stageAndReboot()).show();}
 private void stageAndReboot(){if(verifiedZip==null||!verifiedZip.isFile()){status.setText("No verified update file. Download it first.");return;}install.setEnabled(false);download.setEnabled(false);check.setEnabled(false);status.setText("Staging recovery install with root…");io.execute(()->{try{if(!sha256(verifiedZip).equalsIgnoreCase(release.getString("sha256")))throw new Exception("Verified file changed; download again");String path=verifiedZip.getAbsolutePath().replace("'","'\\''");String dest=RECOVERY_ZIP.replace("'","'\\''");String script="set -e; mkdir -p /sdcard/Download /cache/recovery; cp '"+path+"' '"+dest+"'; chmod 0644 '"+dest+"'; sync; printf '%s\\n' 'install "+RECOVERY_ZIP+"' 'reboot' > /cache/recovery/openrecoveryscript; chmod 0644 /cache/recovery/openrecoveryscript; sync";runRoot(script);runOnUiThread(()->status.setText("Recovery script staged. Rebooting into recovery…"));runRoot("reboot recovery");runOnUiThread(()->{status.setText("Reboot command returned. If the phone did not reboot, check root permission and recovery compatibility.");check.setEnabled(true);download.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("Could not stage update: "+e.getMessage());install.setEnabled(true);download.setEnabled(true);check.setEnabled(true);});}});}
 private void runRoot(String command)throws Exception{Process p=new ProcessBuilder("su","-c",command).redirectErrorStream(true).start();ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=p.getInputStream()){byte[] x=new byte[4096];int n;while((n=in.read(x))!=-1){if(b.size()<32768)b.write(x,0,n);}}if(!p.waitFor(30,java.util.concurrent.TimeUnit.SECONDS)){p.destroyForcibly();throw new Exception("Root command timed out");}int code=p.exitValue();if(code!=0)throw new Exception("su exit "+code+": "+b.toString("UTF-8"));}
 private String sha256(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[131072];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private TextView text(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,1);return t;}private void add(LinearLayout p,View v,int top){LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,-2);l.topMargin=top;p.addView(v,l);}private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}